"브라질\": [-52, -10], \"오스트리아\": [14.5, 47.5], \"캄보디아\": [105, 12.5], \"스리랑카\": [80.7, 7.8], \"세네갈\": [-14.5, 14.5], \"타이완\": [121, 23.7],\n  \"페루\": [-75, -10], \"크로아티아\": [16, 45.2], \"짐바브웨\": [30, -19], \"영국\": [-2, 54], \"싱가포르\": [103.8, 1.35], \"그리스\": [22, 39],\n  \"튀니지\": [9.5, 34], \"가나\": [-1.2, 7.9], \"몰타\": [14.4, 35.9], \"슬로베니아\": [14.8, 46.1], \"에콰도르\": [-78, -1.5], \"캐나다\": [-106, 56],\n  \"핀란드\": [26, 64], \"말레이시아\": [102, 4], \"독일\": [10.4, 51], \"요르단\": [36.5, 31], \"부탄\": [90.4, 27.4], \"보츠와나\": [24, -22],\n  \"이스라엘\": [35, 31.4], \"타지키스탄\": [71, 38.8], \"덴마크\": [10, 56], \"프랑스\": [2.3, 46.6], \"잠비아\": [27.8, -13.1], \"오만\": [57, 21],\n  \"탄자니아\": [35, -6.4], \"에티오피아\": [40, 9], \"헝가리\": [19.5, 47], \"라트비아\": [24.6, 56.9], \"조지아\": [43.5, 42.2], \"우루과이\": [-56, -33],\n  \"홍콩\": [114.2, 22.3], \"말라위\": [34, -13.5], \"우간다\": [32.4, 1.4], \"베네수엘라\": [-66, 7], \"그린란드\": [-42, 72], \"이란\": [53, 32.5],\n  \"코스타리카\": [-84, 9.9], \"슬로바키아\": [19.5, 48.7], \"남아프리카공화국\": [24.5, -29], \"팔라우\": [134.5, 7.5], \"폴란드\": [19.4, 52],\n  \"카타르\": [51.2, 25.3], \"사우디아라비아\": [45, 24], \"마카오\": [113.55, 22.2], \"포르투갈\": [-8, 39.6], \"체코\": [15.5, 49.8], \"아르메니아\": [45, 40.2],\n  \"프랑스령 폴리네시아\": [-149.4, -17.7], \"자메이카\": [-77.3, 18.1], \"케냐\": [37.9, 0.2], \"알제리\": [2.6, 28], \"키르기스스탄\": [74.6, 41.2],\n  \"몬테네그로\": [19.3, 42.7], \"모리타니\": [-10.9, 20.3], \"파라과이\": [-58, -23], \"콜롬비아\": [-74, 4], \"멕시코\": [-102, 23], \"쿠바\": [-79.5, 21.6]\n};\nconst regions = DATA.regions.filter(r => POS[r.name]);\nconst countries = DATA.countries.filter(c => CPOS[c.name]);\ndocument.getElementById(\"sub\").textContent =\n  `OLIFE <걸어서 세계속으로>·<세계테마기행> · ${DATA.period} · ${DATA.target} · 방송 ${regions.reduce((a, r) => a + r.n, 0)}건(여러 권역·국가 방송은 중복 집계)`;\n\nlet mode = \"idxM\", view = \"country\";\nconst W = 1200, H = 600;\nconst svg = d3.select(\"#map\");\nconst defs = svg.append(\"defs\");\nconst gl = defs.append(\"radialGradient\").attr(\"id\", \"gloss\").attr(\"cx\", \"30%\").attr(\"cy\", \"25%\").attr(\"r\", \"75%\");\ngl.append(\"stop\").attr(\"offset\", \"0%\").attr(\"stop-color\", \"#fff\").attr(\"stop-opacity\", .5);\ngl.append(\"stop\").attr(\"offset\", \"55%\").attr(\"stop-color\", \"#fff\").attr(\"stop-opacity\", 0);\nconst proj = d3.geoNaturalEarth1().scale(210).translate([W / 2, H / 2 + 20]);\nconst path = d3.geoPath(proj);\nconst css = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();\nconst color = d3.scaleLinear().domain([0.75, 1, 1.15]).clamp(true);\nfunction ringColor(v) { color.range([css(\"--down\"), css(\"--mid\"), css(\"--up\")]); return color(v); }\nconst radR = r => 9 + 3.1 * Math.sqrt(r.n);\nconst radC = c => 4.5 + 2.6 * Math.sqrt(c.n);\nconst rad = e => view === \"region\" ? radR(e) : radC(e);\nconst items = () => view === \"region\" ? regions : countries;\nconst posOf = e => view === \"region\" ? POS[e.name] : CPOS[e.name];\n\nfetch(\"https://cdn.jsdelivr.net/npm/world-atlas@2.0.2/countries-110m.json\").then(r => r.json()).then(topo => {\n  svg.append(\"path\").datum(d3.geoGraticule10()).attr(\"d\", path).attr(\"fill\", \"none\").attr(\"stroke\", \"var(--grid)\").attr(\"stroke-width\", .8);\n  const land = topojson.feature(topo, topo.objects.countries);\n  svg.append(\"g\").selectAll(\"path\").data(land.features.filter(f => f.id !== \"010\")).join(\"path\").attr(\"d\", path)\n    .attr(\"fill\", \"var(--land)\").attr(\"stroke\", \"var(--land-line)\").attr(\"stroke-width\", .5);\n  refresh();\n}).catch(() => { refresh(); d3.select(\"#sub\").append(\"span\").text(\" (지도 윤곽을 불러오지 못했습니다 — 인터넷 연결 확인)\"); });\n\n// 충돌 회피 배치: 실제 위치(anchor)에서 시작해 서로 겹치지 않게 밀어낸다.\nlet nodes = [];\nfunction layout() {\n  nodes = items().map(r => { const [x, y] = proj(posOf(r)); return { r, ax: x, ay: y, x, y, rad: rad(r) + (view === \"region\" ? 7 : 2) }; });\n  const sim = d3.forceSimulation(nodes)\n    .force(\"x\", d3.forceX(d => d.ax).strength(.12)).force(\"y\", d3.forceY(d => d.ay).strength(.12))\n    .force(\"c\", d3.forceCollide(d => d.rad + 1.5).iterations(4)).stop();\n  for (let i = 0; i < 400; i++) sim.tick();\n  nodes.forEach(n => { n.x = Math.max(n.rad, Math.min(W - n.rad, n.x)); n.y = Math.max(n.rad, Math.min(H - n.rad, n.y)); });\n}\n\nlet selected = null;\nconst tip = document.getElementById(\"tip\");\nfunction draw() {\n  svg.selectAll(\".layer\").remove();\n  const g = svg.append(\"g\").attr(\"class\", \"layer\");\n  g.selectAll(\"line\").data(nodes.filter(n => Math.hypot(n.x - n.ax, n.y - n.ay) > n.rad)).join(\"line\").attr(\"class\", \"lead\")\n    .attr(\"x1\", d => d.ax).attr(\"y1\", d => d.ay).attr(\"x2\", d => d.x).attr(\"y2\", d => d.y);\n  g.selectAll(\"circle.anchor\").data(nodes).join(\"circle\").attr(\"class\", \"anchor\").attr(\"r\", 2).attr(\"cx\", d => d.ax).attr(\"cy\", d => d.ay).attr(\"fill\", \"var(--sub)\");\n  const p = g.selectAll(\"g.pie\").data(nodes).join(\"g\").attr(\"class\", d => \"pie\" + (selected === d.r.name ? \" sel\" : \"\"))\n    .attr(\"transform\", d => `translate(${d.x},${d.y})`).style(\"opacity\", d => d.r.sample ? 1 : .55)\n    .on(\"click\", (e, d) => select(d.r.name))\n    .on(\"mousemove\", (e, d) => showTip(e, d.r)).on(\"mouseleave\", () => tip.style.opacity = 0);\n  const arc = d3.arc(), pie = d3.pie().sort(null).value(d => d.v);\n  p.each(function (d) {\n    const r = d.r, ro = rad(r), gg = d3.select(this);\n    if (view === \"region\") {\n      const parts = [{ v: r.natureOnly, c: \"--nat\" }, { v: r.cultureOnly, c: \"--cul\" }, { v: r.both, c: \"--both\" }, { v: r.neither, c: \"--none\" }].filter(x => x.v > 0);\n      gg.selectAll(\"path\").data(pie(parts)).join(\"path\").attr(\"d\", a => arc.innerRadius(0).outerRadius(ro)(a)).attr(\"fill\", a => `var(${a.data.c})`).attr(\"stroke\", \"var(--glass-line)\").attr(\"stroke-width\", 1);\n      gg.append(\"circle\").attr(\"r\", ro).attr(\"fill\", \"url(#gloss)\").attr(\"pointer-events\", \"none\");\n      gg.append(\"circle\").attr(\"class\", \"ring\").attr(\"r\", ro + 3.5).attr(\"stroke\", ringColor(r[mode])).attr(\"stroke-dasharray\", r.sample ? null : \"3 3\");\n      gg.append(\"text\").attr(\"y\", ro + 18).text(`${r.name} ${r[mode].toFixed(2)}`);\n    } else {\n      gg.append(\"circle\").attr(\"r\", ro).attr(\"fill\", ringColor(r[mode])).attr(\"stroke\", \"#fff\").attr(\"stroke-width\", 1.5).attr(\"stroke-dasharray\", r.sample ? null : \"3 2\");\n      gg.append(\"circle\").attr(\"r\", ro).attr(\"fill\", \"url(#gloss)\").attr(\"pointer-events\", \"none\");\n      if (r.n >= 5 || selected === r.name) gg.append(\"text\").attr(\"y\", ro + 12).text(r.name);\n    }\n  });\n}\nconst chipsOf = a => a.length ? a.map(([t, n]) => `${t} ${n}`).join(\", \") : \"-\";\nfunction showTip(e, r) {\n  const places = (r.places || []).slice(0, 6).map(p => `${p.name} ${p.n}건·${p.idxM.toFixed(2)}`).join(\"<br>\");\n  const cs = (r.countries || []).slice(0, 5).map(c => `${c.name} ${c.n}건·${c.idxM.toFixed(2)}`).join(\"<br>\");\n  tip.innerHTML = `<b>${r.name}</b>${r.region ? ` <span style=\"opacity:.7\">${r.region}</span>` : \"\"}<br>월보정지수 ${r.idxM.toFixed(2)} · 슬롯지수 ${r.idx.toFixed(2)}<br>방송 ${r.n}건 · 회차 ${r.episodes}편 · 평균 ${r.rating.toFixed(3)}%${r.sample ? \"\" : \"<br>표본 적음(참고용)\"}` +\n    (places ? `<br><span style=\"opacity:.7\">도시·장소(방송수·지수)</span><br>${places}` : \"\") +\n    (cs ? `<br><span style=\"opacity:.7\">주요 국가(방송수·지수)</span><br>${cs}` : \"\") +\n    (r.themes && r.themes.length ? `<br><span style=\"opacity:.7\">테마</span> ${chipsOf(r.themes)}` : \"\");\n  tip.style.opacity = 1; tip.style.left = Math.min(innerWidth - 260, e.clientX + 14) + \"px\"; tip.style.top = Math.min(innerHeight - 220, e.clientY + 14) + \"px\";\n}\nfunction select(name) { selected = name; draw(); renderRank(); renderDetail(); }\nfunction renderRank() {\n  const rs = [...items()].sort((a, b) => (b.sample - a.sample) || (b[mode] - a[mode])); // 표본 충분한 항목을 먼저, 참고용은 뒤로\n  document.getElementById(\"rankTitle\").textContent = (view === \"region\" ? \"권역\" : \"국가\") + (mode === \"idxM\" ? \" · 월보정지수\" : \" · 슬롯지수\");\n  const ul = d3.select(\"#rank\");\n  ul.selectAll(\"li\").remove();\n  rs.forEach(r => {\n    const li = ul.append(\"li\").attr(\"class\", selected === r.name ? \"sel\" : \"\").on(\"click\", () => select(r.name));\n    li.append(\"span\").text(r.name);\n    li.append(\"span\").attr(\"class\", \"bar\").append(\"i\").style(\"width\", Math.max(4, Math.min(100, (r[mode] - 0.6) / 0.7 * 100)) + \"%\").style(\"background\", ringColor(r[mode])).style(\"opacity\", r.sample ? 1 : .45);\n    li.append(\"span\").attr(\"class\", \"v\").html(r[mode].toFixed(2) + (r.sample ? \"\" : '<span class=\"ref\">*</span>'));\n  });\n}\nfunction renderDetail() {\n  const r = items().find(x => x.name === selected); const el = document.getElementById(\"detail\");\n  if (!r) { el.textContent = \"원이나 순위 항목을 누르세요.\"; return; }\n  const chip = (t) => `<span class=\"chip\">${t}</span>`;\n  el.innerHTML = `<b>${r.name}</b> — 방송 ${r.n}건, 회차 ${r.episodes}편, 평균 ${r.rating.toFixed(3)}%${r.sample ? \"\" : \" (참고용)\"}<br>` +\n    `월보정지수 <b>${r.idxM.toFixed(2)}</b> · 슬롯지수 <b>${r.idx.toFixed(2)}</b><br>` +\n    (view === \"region\"\n      ? `자연 테마 ${r.topNature.map(([t, n]) => chip(t + \" \" + n)).join(\"\") || \"-\"}<br>문화 테마 ${r.topCulture.map(([t, n]) => chip(t + \" \" + n)).join(\"\") || \"-\"}<br>주요 국가 ${r.countries.map(c => chip(`${c.name} ${c.n}건·${c.idxM.toFixed(2)}`)).join(\"\")}`\n      : `테마 ${r.themes.map(([t, n]) => chip(t + \" \" + n)).join(\"\") || \"-\"}<br>도시·장소 ${r.places.length ? r.places.map(p => chip(`${p.name} ${p.n}건·${p.idxM.toFixed(2)}`)).join(\"\") : \"-\"}`);\n}\nfunction refresh() { layout(); draw(); renderRank(); renderDetail(); }\nfunction setMode(m) {\n  mode = m;\n  document.getElementById(\"mM\").setAttribute(\"aria-pressed\", m === \"idxM\"); document.getElementById(\"mS\").setAttribute(\"aria-pressed\", m === \"idx\");\n  draw(); renderRank();\n}\nfunction setView(v) {\n  view = v; selected = null;\n  document.getElementById(\"vC\").setAttribute(\"aria-pressed\", v === \"country\"); document.getElementById(\"vR\").setAttribute(\"aria-pressed\", v === \"region\");\n  document.getElementById(\"legPie\").style.display = v === \"region\" ? \"\" : \"none\";\n  refresh();\n}\ndocument.getElementById(\"mM\").onclick = () => setMode(\"idxM\");\ndocument.getElementById(\"mS\").onclick = () => setMode(\"idx\");\ndocument.getElementById(\"vC\").onclick = () => setView(\"country\");\ndocument.getElementById(\"vR\").onclick = () => setView(\"region\");\nmatchMedia(\"(prefers-color-scheme: dark)\").addEventListener(\"change\", () => { draw(); renderRank(); });\ndocument.getElementById(\"legPie\").style.display = \"none\";\n</script>\n</body>\n</html>\n";
